<cu-select id="selector"></cu-select>

<script>
  const sel = document.getElementById('selector');
  sel.options = [
    { value: 'op1', label: 'Opción 1' },
    { value: 'op2', label: 'Opción 2' },
  ];

  sel.addEventListener('select', (e) => {
